//!   beside `[install] release-bin` naming the commit `@-` the build
//!   was made from and whether `@` was empty. Nothing on the PATH is
//!   replaced: the staged binary is run by `vc-x1 run` and deployed
//!   by `vc-x1 install-global`, which reads the stamp.
//! - `vc-x1 install --dev` runs `[install] dev`, the dev build
//!   under its own root, and writes no stamp.
//! - Neither checks the repo's state: a release may be staged from a
//!   cycle's bookmark, to try the release profile mid-cycle. The
//!   check that a release is pushed `main` belongs to the step
//!   consumers see, the deployment.
//! - The stamp is removed before the build and written after it
//!   passes, so a failed build never leaves a stamp describing the
//!   binary it failed to replace.
//! - The lists are run by [`crate::command_list`], as `validate`'s
//!   are.

use std::path::{Path, PathBuf};

use clap::Args;
use log::{debug, info};

use crate::context::Context;
use crate::subcommand::SubcommandRunner;

/// The stamp's suffix, appended to the release binary's path.
pub const STAMP_SUFFIX: &str = ".stamp";

/// Stage the release build, or install the dev build with `--dev`.
#[derive(Args, Debug)]
pub struct InstallArgs {
    /// Run `[install] dev`, the dev build, instead of staging the
    /// release, and write no stamp
    #[arg(long)]
    pub dev: bool,

    /// Workspace to install from [default: the workspace containing
    /// the current directory]
    #[arg(short = 'R', long, value_name = "DIR")]
    pub repo: Option<PathBuf>,
}

/// What a release stamp records: where it goes and the build's
/// provenance, read before the build runs.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Stamp {
    /// The stamp file, `[install] release-bin` plus [`STAMP_SUFFIX`].
    pub path: PathBuf,
    /// The binary the stamp describes, `[install] release-bin`.
    pub bin: PathBuf,
    /// The full commit id of the work repo's `@-`.
    pub commit: String,
    /// True when the work repo's `@` was empty, so the build is
    /// exactly `commit`'s tree.
    pub clean: bool,
}

/// Per-invocation install inputs: the list's key, its commands, the
/// directory to run them from, and the stamp a release writes.
#[derive(Debug)]
pub struct InstallParams {
    /// `install.release` or `install.dev`.
    pub key: &'static str,
    /// The commands, one element per invocation.
    pub commands: Vec<String>,
    /// The work repo root the commands run from.
    pub root: PathBuf,
    /// The release's stamp, `None` for the dev build.
    pub stamp: Option<Stamp>,
}

impl TryFrom<&InstallArgs> for InstallParams {
    type Error = String;

    /// Resolve the workspace root (from `-R` or the cwd), take the
    /// chosen list, and for a release resolve `release-bin` and read
    /// the provenance. Every miss is an error here, before anything
    /// runs.
    fn try_from(a: &InstallArgs) -> Result<Self, String> {
        let key = if a.dev {
            "install.dev"
        } else {
            "install.release"
        };
        let root = match &a.repo {
            Some(p) => crate::common::find_workspace_root_from(p).ok_or_else(|| {
                format!("install: '{}' is not in a vc-x1 workspace", p.display())
            })?,
            None => crate::common::find_workspace_root().ok_or_else(|| {
                "install: not in a vc-x1 workspace (no config found)".to_string()
            })?,
        };
        let commands = crate::command_list::load(&root, key, "install")?;
        let stamp = if a.dev {
            None
        } else {
            let bin = release_bin(&root)?;
            let commit = crate::jj::cid_of(&root, "@-")
                .map_err(|e| format!("install: the commit `@-` in '{}': {e}", root.display()))?;
            let clean = crate::jj::is_empty(&root, "@")
                .map_err(|e| format!("install: whether `@` is empty in '{}': {e}", root.display()))?;
            Some(Stamp {
                path: stamp_path(&bin),
                bin,
                commit,
                clean,
            })
        };
        Ok(InstallParams {
            key,
            commands,
            root,
            stamp,
        })
    }
}

/// `[install] release-bin` at `root`, resolved against the config
/// file's directory, or as is when absolute. Required for a release,
/// since the stamp sits beside it.
pub fn release_bin(root: &Path) -> Result<PathBuf, String> {
    let cfg = crate::config_md::load(root)
        .map_err(|e| format!("install: {e}"))?
        .ok_or_else(|| format!("install: no config in '{}'", root.display()))?;
    let value = crate::toml_simple::toml_get(&cfg.map, "install.release-bin").ok_or_else(|| {
        format!(
            "install: {}: no `install.release-bin`, the binary `install.release` leaves, \
             which the stamp is written beside (see `vc-x1 config work`)",
            cfg.path.display()
        )
    })?;
    // OK: a loaded config's path is a file, so it has a parent
    let cfg_dir = cfg.path.parent().unwrap_or(root);
    Ok(crate::common::resolve_repo_path(cfg_dir, value))
}

/// The stamp file for the binary at `bin`.
pub fn stamp_path(bin: &Path) -> PathBuf {
    let mut s = bin.as_os_str().to_os_string();
    s.push(STAMP_SUFFIX);
    PathBuf::from(s)
}

/// The stamp's text: a comment saying what it is, then `commit` and
/// `clean`, keys `toml_simple` reads back.
pub fn render_stamp(stamp: &Stamp) -> String {
    format!(
        "# vc-x1 install stamp: the commit the binary beside it was built from\n\
         commit = \"{}\"\n\
         clean = {}\n",
        stamp.commit, stamp.clean
    )
}

impl SubcommandRunner for InstallArgs {
    type Params = InstallParams;

    /// Delegate to the `TryFrom<&InstallArgs>` impl above.
    fn to_params(&self) -> Result<Self::Params, String> {
        InstallParams::try_from(self)
    }

    /// Run the `install` op (`ctx` unused: the op is fully
    /// parameterized by `Params`).
    fn run(_ctx: &mut Context, params: &Self::Params) -> Result<(), Box<dyn std::error::Error>> {
        install(params)
    }
}

/// Run the list from the root, and for a release remove the old
/// stamp first and write the new one once the list passes.
pub fn install(params: &InstallParams) -> Result<(), Box<dyn std::error::Error>> {
    debug!("install: entry params={params:?}");
    if let Some(stamp) = &params.stamp {
        match std::fs::remove_file(&stamp.path) {
            Ok(()) => debug!("install: removed the old stamp {}", stamp.path.display()),
            Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
            Err(e) => {
                return Err(format!(
                    "install: cannot remove the old stamp '{}': {e}",
                    stamp.path.display()
                )
                .into());
            }
        }
    }
    crate::command_list::run(&params.root, params.key, &params.commands, "install")?;
    let Some(stamp) = &params.stamp else {
        return Ok(());
    };
    if !stamp.bin.is_file() {
        return Err(format!(
            "install: `{}` passed but left no binary at '{}', so no stamp is written: \
             check `install.release-bin`",
            params.key,
            stamp.bin.display()
        )
        .into());
    }
    std::fs::write(&stamp.path, render_stamp(stamp))
        .map_err(|e| format!("install: cannot write the stamp '{}': {e}", stamp.path.display()))?;
    let short = &stamp.commit[..stamp.commit.len().min(12)];
    let state = if stamp.clean {
        "`@` empty"
    } else {
        "`@` not empty, so the build is not exactly that commit"
    };
    info!(
        "install: staged {}, built from {short}, {state}",
        stamp.bin.display()
    );
    Ok(())
}

#[cfg(test)]
mod tests {
    use super::*;
    use crate::{Cli, Commands};
    use clap::Parser;

    fn parse(args: &[&str]) -> InstallArgs {
        let cli = Cli::try_parse_from(args).unwrap();
        match cli.command {
            Some(Commands::Install(a)) => a,
            _ => panic!("expected Install"),
        }
    }

    /// Unique tempdir for a one-file workspace.
    fn workspace(tag: &str, config: &str) -> PathBuf {
        let ts = std::time::SystemTime::now()
            .duration_since(std::time::UNIX_EPOCH)
            .unwrap()
            .as_nanos();
        let root = std::env::temp_dir().join(format!("vc-x1-install-{tag}-{ts}"));
        std::fs::create_dir_all(&root).unwrap();
        std::fs::write(root.join(".vc-config.md"), config).unwrap();
        root
    }

    fn stamp_in(root: &Path) -> Stamp {
        let bin = root.join("rel/bin/app");
        Stamp {
            path: stamp_path(&bin),
            bin,
            commit: "0123456789abcdef0123456789abcdef01234567".to_string(),
            clean: true,
        }
    }

    #[test]
    fn flags_parse() {
        let a = parse(&["vc-x1", "install"]);
        assert!(!a.dev);
        assert_eq!(a.repo, None);
        let a = parse(&["vc-x1", "install", "--dev", "-R", "x"]);
        assert!(a.dev);
        assert_eq!(a.repo, Some(PathBuf::from("x")));
    }

    /// The stamp sits beside the binary, the suffix appended.
    #[test]
    fn stamp_path_appends_the_suffix() {
        assert_eq!(
            stamp_path(Path::new("tmp/rel/bin/vc-x1")),
            PathBuf::from("tmp/rel/bin/vc-x1.stamp")
        );
    }

    /// The stamp's keys read back through toml_simple, the reader
    /// install-global uses.
    #[test]
    fn stamp_reads_back() {
        let root = workspace("readback", "");
        let mut stamp = stamp_in(&root);
        stamp.clean = false;
        let map = crate::toml_simple::toml_parse(&render_stamp(&stamp));
        assert_eq!(
            crate::toml_simple::toml_get(&map, "commit").map(String::as_str),
            Some(stamp.commit.as_str())
        );
        assert_eq!(
            crate::toml_simple::toml_get(&map, "clean").map(String::as_str),
            Some("false")
        );
        std::fs::remove_dir_all(&root).ok();
    }

    /// A release without `release-bin` is refused before anything
    /// runs, naming the key.
    #[test]
    fn release_needs_release_bin() {
        let root = workspace(
            "nobin",
            "```toml\n[repos]\nwork = \".\"\n[install]\nrelease = [\"true\"]\n```\n",
        );
        let e = release_bin(&root).unwrap_err();
        assert!(e.contains("no `install.release-bin`"), "{e}");
        std::fs::remove_dir_all(&root).ok();
    }

    /// `release-bin` resolves against the config file's directory,
    /// or as is when absolute.
    #[test]
    fn release_bin_resolves_against_the_config() {
        let root = workspace(
            "rel",
            "```toml\n[repos]\nwork = \".\"\n[install]\nrelease-bin = \"rel/bin/app\"\n```\n",
        );
        assert_eq!(release_bin(&root).unwrap(), root.join("rel/bin/app"));
        let root2 = workspace(
            "abs",
            "```toml\n[repos]\nwork = \".\"\n[install]\nrelease-bin = \"/opt/app\"\n```\n",
        );
        assert_eq!(release_bin(&root2).unwrap(), PathBuf::from("/opt/app"));
        std::fs::remove_dir_all(&root).ok();
        std::fs::remove_dir_all(&root2).ok();
    }

    /// A passing release writes the stamp beside the binary it left,
    /// replacing an old one.
    #[test]
    fn release_writes_the_stamp() {
        let root = workspace("stamp", "");
        let stamp = stamp_in(&root);
        std::fs::create_dir_all(stamp.bin.parent().unwrap()).unwrap();
        std::fs::write(&stamp.path, "old").unwrap();
        let params = InstallParams {
            key: "install.release",
            commands: vec!["touch rel/bin/app".to_string()],
            root: root.clone(),
            stamp: Some(stamp.clone()),
        };
        install(&params).unwrap();
        assert_eq!(
            std::fs::read_to_string(&stamp.path).unwrap(),
            render_stamp(&stamp)
        );
        std::fs::remove_dir_all(&root).ok();
    }

    /// A failed release removes the old stamp and writes none, so no
    /// stamp describes the binary the build failed to replace.
    #[test]
    fn failed_release_leaves_no_stamp() {
        let root = workspace("fail", "");
        let stamp = stamp_in(&root);
        std::fs::create_dir_all(stamp.bin.parent().unwrap()).unwrap();
        std::fs::write(&stamp.bin, "the previous build").unwrap();
        std::fs::write(&stamp.path, "old").unwrap();
        let params = InstallParams {
            key: "install.release",
            commands: vec!["false".to_string()],
            root: root.clone(),
            stamp: Some(stamp.clone()),
        };
        let e = install(&params).unwrap_err().to_string();
        assert!(e.contains("`false` failed"), "{e}");
        assert!(!stamp.path.exists(), "the old stamp survived a failed build");
        std::fs::remove_dir_all(&root).ok();
    }

    /// A release whose list passes but leaves no binary at
    /// `release-bin` is an error, and no stamp is written.
    #[test]
    fn release_without_its_binary_errors() {
        let root = workspace("nobinary", "");
        let stamp = stamp_in(&root);
        let params = InstallParams {
            key: "install.release",
            commands: vec!["true".to_string()],
            root: root.clone(),
            stamp: Some(stamp.clone()),
        };
        let e = install(&params).unwrap_err().to_string();
        assert!(e.contains("left no binary"), "{e}");
        assert!(!stamp.path.exists());
        std::fs::remove_dir_all(&root).ok();
    }

    /// The dev build runs its list and writes no stamp.
    #[test]
    fn dev_writes_no_stamp() {
        let root = workspace("dev", "");
        let params = InstallParams {
            key: "install.dev",
            commands: vec!["touch dev-ran".to_string()],
            root: root.clone(),
            stamp: None,
        };
        install(&params).unwrap();
        assert!(root.join("dev-ran").exists());
        let stamps: Vec<_> = std::fs::read_dir(&root)
            .unwrap()
            .filter_map(|e| e.ok())
            .filter(|e| e.file_name().to_string_lossy().ends_with(STAMP_SUFFIX))
            .collect();
        assert!(stamps.is_empty());
        std::fs::remove_dir_all(&root).ok();
    }
}

