/// subcommand `--help` output: `<invoked name> <version>`.
fn banner() -> &'static str {
    static BANNER: std::sync::OnceLock<String> = std::sync::OnceLock::new();
    BANNER.get_or_init(|| format!("{} {}", invoked_name(), env!("CARGO_PKG_VERSION")))
}

/// The banner a run prints: the plain banner plus the workspace's
/// set version, ` (agent-files v0.1.0)`, when the current directory
/// is in a workspace that records one. Help keeps the plain banner,
/// since help is not a run and its text must not depend on the cwd.
fn run_banner() -> String {
    let root = common::find_workspace_root();
    format!(
        "{}{}",
        banner(),
        agent_files::banner_suffix(root.as_deref())
    )
}

/// Top-level about line: name, version, and the project tagline
/// on a single line. Used as the top-level `about` so `vc-x1 -h`
/// reads as one banner-plus-tagline header instead of two stacked
/// lines.
fn top_about() -> String {
    format!("{} - jj workspace tooling", banner())
}

/// Build the clap command tree with `BANNER` set as `before_help`
/// on every subcommand (transitively). Top-level skips `before_help`
/// because its own `about` already carries the name+version+tagline.
/// Walks via `mut_subcommand` so individual subcommand
/// `#[command(long_about = ...)]` blocks don't have to repeat the
/// banner text.
fn cli_with_banner() -> clap::Command {
    fn add_to_subs(mut cmd: clap::Command) -> clap::Command {
        let names: Vec<String> = cmd
            .get_subcommands()
            .map(|c| c.get_name().to_string())
            .collect();
        for name in names {
            cmd = cmd.mut_subcommand(name, add_with_banner);
        .collect();
    out.sort();
    out
}

/// The banner's tail: ` (agent-files v0.1.0)`, or empty outside a
/// workspace and when the workspace has no version file.
pub fn banner_suffix(work_root: Option<&Path>) -> String {
    match work_root.map(versions) {
        Some(vs) if !vs.is_empty() => format!(" (agent-files {})", vs.join(", ")),
        _ => String::new(),
    }
}

/// The `vc-x1 version` line for the set, a `none` with its reason
/// when there is nothing to report.
pub fn report_line(work_root: Option<&Path>) -> String {
    match work_root {
        None => "agent-files none: not in a vc-x1 workspace".to_string(),
        Some(root) => {
            let vs = versions(root);
            if vs.is_empty() {
                format!("agent-files none: no agent-data/{PREFIX}v* file")
            } else {
                format!("agent-files {}", vs.join(", "))
            }

