1	//! The `install` subcommand: stage the workspace's release build, or
2	//! with `--dev` install its dev build, each by its configured
3	//! command list.
4	//!
5	//! - `vc-x1 install` runs `[install] release`, which builds the
6	//!   release under its own root (`tmp/rel` here), and writes a stamp
7	//!   beside `[install] release-bin` naming the commit `@-` the build
8	//!   was made from and whether `@` was empty. Nothing on the PATH is
9	//!   replaced: the staged binary is run by `vc-x1 run` and deployed
10	//!   by `vc-x1 install-global`, which reads the stamp.
11	//! - The release's commands run with `VC_X1_BUILD_COMMIT`, the
12	//!   stamp's commit, and `VC_X1_BUILD_CLEAN`, `true` or `false`, in
13	//!   their environment, so an artifact that compiles them in can say
14	//!   what it was built from wherever it is copied. vc-x1 does, as
15	//!   semver build metadata in its banner, `0.85.7+d70cf9ecdfd9`.
16	//! - `vc-x1 install --dev` runs `[install] dev`, the dev build
17	//!   under its own root, and writes no stamp. It sets neither
18	//!   variable, so the dev build still reuses the test build.
19	//! - Neither checks the repo's state: a release may be staged from a
20	//!   cycle's bookmark, to try the release profile mid-cycle. The
21	//!   check that a release is pushed `main` belongs to the step
22	//!   consumers see, the deployment.
23	//! - The stamp is removed before the build and written after it
24	//!   passes, so a failed build never leaves a stamp describing the
25	//!   binary it failed to replace.
26	//! - The lists are run by [`crate::command_list`], as `validate`'s
27	//!   are.
28	
29	use std::path::{Path, PathBuf};
30	
31	use clap::Args;
32	use log::{debug, info};
33	
34	use crate::context::Context;
35	use crate::subcommand::SubcommandRunner;
36	
37	/// The stamp's suffix, appended to the release binary's path.
38	pub const STAMP_SUFFIX: &str = ".stamp";
39	
40	/// The variable carrying the release's commit to its build.
41	pub const BUILD_COMMIT_VAR: &str = "VC_X1_BUILD_COMMIT";
42	
43	/// The variable carrying whether `@` was empty, `true` or `false`.
44	pub const BUILD_CLEAN_VAR: &str = "VC_X1_BUILD_CLEAN";
45	
46	/// Stage the release build, or install the dev build with `--dev`.
47	#[derive(Args, Debug)]
48	pub struct InstallArgs {
49	    /// Run `[install] dev`, the dev build, instead of staging the
50	    /// release, and write no stamp
51	    #[arg(long)]
52	    pub dev: bool,
53	
54	    /// Workspace to install from [default: the workspace containing
55	    /// the current directory]
56	    #[arg(short = 'R', long, value_name = "DIR")]
57	    pub repo: Option<PathBuf>,
58	}
59	
60	/// What a release stamp records: where it goes and the build's
61	/// provenance, read before the build runs.
62	#[derive(Debug, Clone, PartialEq, Eq)]
63	pub struct Stamp {
64	    /// The stamp file, `[install] release-bin` plus [`STAMP_SUFFIX`].
65	    pub path: PathBuf,
66	    /// The binary the stamp describes, `[install] release-bin`.
67	    pub bin: PathBuf,
68	    /// The full commit id of the work repo's `@-`.
69	    pub commit: String,
70	    /// True when the work repo's `@` was empty, so the build is
71	    /// exactly `commit`'s tree.
72	    pub clean: bool,
73	}
74	
75	/// Per-invocation install inputs: the list's key, its commands, the
76	/// directory to run them from, and the stamp a release writes.
77	#[derive(Debug)]
78	pub struct InstallParams {
79	    /// `install.release` or `install.dev`.
80	    pub key: &'static str,
81	    /// The commands, one element per invocation.
82	    pub commands: Vec<String>,
83	    /// The work repo root the commands run from.
84	    pub root: PathBuf,
85	    /// The release's stamp, `None` for the dev build.
86	    pub stamp: Option<Stamp>,
87	}
88	
89	impl TryFrom<&InstallArgs> for InstallParams {
90	    type Error = String;
91	
92	    /// Resolve the workspace root (from `-R` or the cwd), take the
93	    /// chosen list, and for a release resolve `release-bin` and read
94	    /// the provenance. Every miss is an error here, before anything
95	    /// runs.
96	    fn try_from(a: &InstallArgs) -> Result<Self, String> {
97	        let key = if a.dev {
98	            "install.dev"
99	        } else {
100	            "install.release"
101	        };
102	        let root = match &a.repo {
103	            Some(p) => crate::common::find_workspace_root_from(p)
104	                .ok_or_else(|| format!("install: '{}' is not in a vc-x1 workspace", p.display()))?,
105	            None => crate::common::find_workspace_root()
106	                .ok_or_else(|| "install: not in a vc-x1 workspace (no config found)".to_string())?,
107	        };
108	        let commands = crate::command_list::load(&root, key, "install")?;
109	        let stamp = if a.dev {
110	            None
111	        } else {
112	            let bin = release_bin(&root)?;
113	            let commit = crate::jj::cid_of(&root, "@-")
114	                .map_err(|e| format!("install: the commit `@-` in '{}': {e}", root.display()))?;
115	            let clean = crate::jj::is_empty(&root, "@").map_err(|e| {
116	                format!("install: whether `@` is empty in '{}': {e}", root.display())
117	            })?;
118	            Some(Stamp {
119	                path: stamp_path(&bin),
120	                bin,
121	                commit,
122	                clean,
123	            })
124	        };
125	        Ok(InstallParams {
126	            key,
127	            commands,
128	            root,
129	            stamp,
130	        })
131	    }
132	}
133	
134	/// `[install] release-bin` at `root`, resolved against the config
135	/// file's directory, or as is when absolute. Required for a release,
136	/// since the stamp sits beside it.
137	pub fn release_bin(root: &Path) -> Result<PathBuf, String> {
138	    let cfg = crate::config_md::load(root)
139	        .map_err(|e| format!("install: {e}"))?
140	        .ok_or_else(|| format!("install: no config in '{}'", root.display()))?;
141	    let value = crate::toml_simple::toml_get(&cfg.map, "install.release-bin").ok_or_else(|| {
142	        format!(
143	            "install: {}: no `install.release-bin`, the binary `install.release` leaves, \
144	             which the stamp is written beside (see `vc-x1 config work`)",
145	            cfg.path.display()
