#[test]
fn scope_positional_and_flag() {
    let both = Scope(vec![Side::Work, Side::Bot]);
    assert_eq!(parse(&["t", "both"]).pos_scope, Some(both.clone()));
    assert_eq!(parse(&["t", "-s", "both"]).scope, Some(both));
